from __future__ import annotations

KIRA_MINI_APP_HTML = r'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#160f25"><title>Kira Mini App</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<style>
:root{--bg:#130d1e;--panel:#241936;--panel2:#181020;--line:#6e5088;--accent:#c78cff;--accent2:#ff9fc7;--text:#fff;--muted:#c8b7d7;--ok:#91e7ad;--warn:#ffd27a;font-family:Inter,system-ui,-apple-system,sans-serif;color-scheme:dark}
:root[data-theme="midnight"]{--bg:#07111f;--panel:#10243c;--panel2:#091827;--line:#315d82;--accent:#70b9ff;--accent2:#83ddff}
:root[data-theme="rose"]{--bg:#1d0e17;--panel:#3b1b2c;--panel2:#28101d;--line:#82475f;--accent:#ff82b4;--accent2:#ffc0d8}
:root[data-theme="emerald"]{--bg:#081a16;--panel:#14352d;--panel2:#0b241e;--line:#2e7663;--accent:#5fe0b6;--accent2:#a3f0d7}
:root[data-theme="amber"]{--bg:#1d1307;--panel:#3a2913;--panel2:#291b0c;--line:#80602f;--accent:#ffc45c;--accent2:#ffe0a1}
*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 15% 0,color-mix(in srgb,var(--accent) 28%,transparent),transparent 35%),var(--bg);color:var(--text)}body{padding:env(safe-area-inset-top) 0 calc(86px + env(safe-area-inset-bottom))}main{max-width:820px;margin:auto;padding:16px}.hero,.card{background:color-mix(in srgb,var(--panel) 94%,transparent);border:1px solid color-mix(in srgb,var(--line) 70%,transparent);border-radius:22px;padding:17px;margin-bottom:13px;box-shadow:0 14px 35px #0005}.hero{display:flex;gap:14px;align-items:center}.avatar{width:58px;height:58px;border-radius:19px;display:grid;place-items:center;background:linear-gradient(135deg,var(--accent),var(--accent2));font-size:29px;flex:0 0 auto}.hero h1{font-size:24px;margin:0 0 3px}.muted{color:var(--muted)}.tiny{font-size:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.stat{background:var(--panel2);border:1px solid #ffffff0c;border-radius:16px;padding:13px}.stat b{display:block;font-size:24px;color:var(--accent)}h2,h3{margin:0 0 12px}.tab{display:none}.tab.active{display:block;animation:fade .18s ease}@keyframes fade{from{opacity:.25;transform:translateY(4px)}to{opacity:1;transform:none}}label{display:block;color:var(--muted);font-size:13px;margin:10px 0}input,select,textarea{width:100%;margin-top:5px;padding:12px;border-radius:12px;border:1px solid var(--line);background:var(--panel2);color:var(--text);font:inherit}textarea{min-height:96px;resize:vertical}button{border:0;border-radius:13px;padding:12px 14px;background:var(--accent);color:#160d20;font-weight:800;font:inherit;cursor:pointer}.secondary{background:var(--panel2);color:var(--text);border:1px solid var(--line)}.row{display:flex;gap:8px;align-items:center}.row>*{flex:1}.notice{padding:12px;border-radius:13px;background:#ffffff0a;color:var(--muted);margin:10px 0}.shop-item,.campaign,.command{padding:12px 0;border-bottom:1px solid #ffffff10}.shop-item:last-child,.campaign:last-child,.command:last-child{border:0}.shop-top,.command-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.price{color:var(--warn);font-weight:800}.owned{color:var(--ok);font-weight:700}.dice{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.dice button{background:var(--panel2);color:var(--accent);border:1px solid var(--line)}.result{font-size:28px;font-weight:900;text-align:center;color:var(--warn);padding:13px}.command code{color:var(--accent);font-weight:800}.search{position:sticky;top:4px;z-index:2;background:var(--bg);padding-bottom:8px}.bottom{position:fixed;left:0;right:0;bottom:0;background:color-mix(in srgb,var(--bg) 92%,transparent);backdrop-filter:blur(14px);border-top:1px solid #ffffff18;padding:8px 8px calc(8px + env(safe-area-inset-bottom));z-index:10}.nav{max-width:820px;margin:auto;display:flex;overflow-x:auto;gap:5px}.nav button{min-width:76px;flex:1;background:transparent;color:var(--muted);padding:8px 6px;font-size:11px}.nav button.active{background:color-mix(in srgb,var(--accent) 18%,transparent);color:var(--accent)}.nav strong{display:block;font-size:18px}.toast{position:fixed;left:18px;right:18px;bottom:93px;max-width:620px;margin:auto;background:#30213f;border:1px solid var(--line);border-radius:14px;padding:12px;text-align:center;display:none;z-index:20}.toast.show{display:block}.colorline{height:5px;border-radius:99px;background:var(--accent);margin:8px 0 0}@media(min-width:650px){.grid{grid-template-columns:repeat(4,1fr)}.dice{grid-template-columns:repeat(7,1fr)}}
</style></head><body><main>
<section class="hero"><div class="avatar" id="avatar">🦊</div><div style="min-width:0"><div class="tiny muted">KIRA 1.6 · Mini App</div><h1 id="heroName">Твоя Кира</h1><div class="muted" id="heroSub">Чат с Кирой, профиль, экономика, команды и память.</div><div class="colorline" id="colorLine"></div></div></section>
<div id="authNotice" class="notice" style="display:none">Открой Mini App кнопкой из Telegram, чтобы профиль и сохранения были доступны.</div>
<section id="home" class="tab active">
  <div class="card"><h3>Главная</h3><div class="grid"><div class="stat"><span class="muted">Уровень</span><b id="level">–</b></div><div class="stat"><span class="muted">XP</span><b id="xp">–</b></div><div class="stat"><span class="muted">Монеты</span><b id="coins">–</b></div><div class="stat"><span class="muted">Память</span><b id="memCount">–</b></div></div></div>
  <div class="card"><h3>Что внутри</h3><div class="notice">🎨 Профиль и косметика · 🪙 магазин · 🐉 D&D · 📚 все команды · 🧠 память и приватность. Старые отдельные страницы оставлены только для совместимости.</div><div class="row"><button onclick="go('shop')">🛍 Магазин</button><button class="secondary" onclick="go('chat')">💬 Чат</button></div></div>
</section>
<section id="profile" class="tab"><div class="card"><h3>👤 Профиль</h3>
<label>Ник Киры<input id="nickname" maxlength="32" placeholder="Например: Лис"></label>
<label>Пол<select id="gender"><option value="unspecified">Не указывать</option><option value="male">Мужской</option><option value="female">Женский</option><option value="other">Другое</option></select></label>
<label>Цвет ника / профиля<input id="profileColor" type="color" value="#e8bdff"></label>
<label>Титул<input id="profileTitle" maxlength="48" placeholder="Например: Ночной лис"></label>
<div class="row"><label>Значок<select id="profileBadge"><option>🦊</option><option>⭐</option><option>🔥</option></select></label><label>Тема<select id="profileTheme"><option value="violet">Violet</option><option value="midnight">Midnight</option><option value="rose">Rose</option><option value="emerald">Emerald</option><option value="amber">Amber</option></select></label></div>
<button onclick="saveProfile()">Сохранить профиль</button><div class="notice tiny">Цвет текста в обычных Telegram-сообщениях менять нельзя. Точный цвет отображается здесь, а в чате Кира показывает ближайший цветной значок.</div></div></section>
<section id="shop" class="tab"><div class="card"><h3>🛍 Магазин и косметика</h3><div class="muted">Монеты можно тратить на оформление. Уровни тоже открывают косметику бесплатно.</div><div id="shopList">Загрузка…</div></div></section>
<section id="chat" class="tab"><div class="card"><h3>💬 Чат с Кирой</h3><div id="chatBox" style="height:42vh;min-height:300px;overflow:auto;padding:8px;background:var(--panel2);border-radius:16px"><div class="notice">🦊 Привет! Теперь со мной можно говорить прямо здесь.</div></div><div class="row" style="margin-top:9px"><input id="chatPrompt" maxlength="4000" placeholder="Напиши Кире…"><button style="flex:0 0 54px" onclick="sendChat()">➤</button></div></div></section>
<section id="commands" class="tab"><div class="card"><h3>📚 Все команды</h3><div class="search"><input id="commandSearch" placeholder="Найти команду…" oninput="renderCommands()"></div><div id="commandsList">Загрузка…</div></div></section>
<section id="memory" class="tab"><div class="card"><h3>🧠 Память и приватность</h3><label>Личная память<select id="personalMemory"><option value="1">Включена</option><option value="0">Выключена</option></select></label><label>История в группах<select id="groupHistory"><option value="1">Разрешена</option><option value="0">Запрещена</option></select></label><button onclick="savePrivacy()">Сохранить приватность</button></div><div class="card"><h3>Последняя память</h3><div id="memoryList" class="muted">Загрузка…</div></div></section>
</main>
<div class="bottom"><div class="nav"><button data-tab="home" onclick="go('home')"><strong>🦊</strong>Главная</button><button data-tab="profile" onclick="go('profile')"><strong>👤</strong>Профиль</button><button data-tab="shop" onclick="go('shop')"><strong>🪙</strong>Магазин</button><button data-tab="chat" onclick="go('chat')"><strong>💬</strong>Чат</button><button data-tab="commands" onclick="go('commands')"><strong>📚</strong>Команды</button><button data-tab="memory" onclick="go('memory')"><strong>🧠</strong>Память</button></div></div><div id="toast" class="toast"></div>
<script>
const tg=window.Telegram?.WebApp;tg?.ready();tg?.expand();const init=tg?.initData||'';const H={'X-Telegram-Init-Data':init,'Content-Type':'application/json'};const $=id=>document.getElementById(id);let me=null,commands=[],dndState={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){const e=$('toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2200)}
function go(id){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));location.hash=id;if(id==='shop')loadShop();if(id==='commands')loadCommands()}
function setTheme(t){document.documentElement.dataset.theme=t||'violet'}
async function api(url,opt={}){opt.headers={...H,...(opt.headers||{})};let r=await fetch(url,opt);if(!r.ok){let text=await r.text();throw new Error(text||('HTTP '+r.status))}return r.status===204?null:r.json()}
async function loadMe(){if(!init){$('authNotice').style.display='block';return}try{me=await api('/api/kira/me');$('level').textContent=me.level;$('xp').textContent=me.xp;$('coins').textContent=me.coins;$('memCount').textContent=me.memory_count;$('nickname').value=me.profile.nickname||'';$('gender').value=me.profile.gender||'unspecified';$('profileColor').value=(me.profile.color||'#E8BDFF').toLowerCase();$('profileTitle').value=me.profile.title||'';$('profileBadge').value=me.profile.badge||'🦊';$('profileTheme').value=me.profile.theme||'violet';$('avatar').textContent=me.profile.badge||'🦊';$('heroName').textContent=(me.profile.nickname||'Твоя Кира')+(me.profile.title?' · '+me.profile.title:'');$('colorLine').style.background=me.profile.color||'#E8BDFF';setTheme(me.profile.theme);$('personalMemory').value=me.privacy.personal_memory?'1':'0';$('groupHistory').value=me.privacy.allow_group_history?'1':'0';$('memoryList').innerHTML=me.memory.length?me.memory.map(x=>'• <b>'+esc(x.key)+'</b>: '+esc(x.value)).join('<br>'):'Пока пусто.'}catch(e){$('authNotice').style.display='block';$('authNotice').textContent='Mini App не смог подтвердить Telegram-сессию. Открой его кнопкой внутри бота.'}}
async function saveProfile(){try{let d=await api('/api/kira/profile',{method:'PUT',body:JSON.stringify({nickname:$('nickname').value,gender:$('gender').value,color:$('profileColor').value,title:$('profileTitle').value,badge:$('profileBadge').value,theme:$('profileTheme').value})});toast(d.message||'Профиль сохранён');tg?.HapticFeedback?.notificationOccurred('success');await loadMe()}catch(e){toast('Не сохранено: '+String(e.message).slice(0,120))}}
async function savePrivacy(){try{await api('/api/kira/privacy',{method:'PUT',body:JSON.stringify({personal_memory:$('personalMemory').value==='1',allow_group_history:$('groupHistory').value==='1'})});toast('Приватность сохранена')}catch(e){toast('Ошибка сохранения')}}
async function loadShop(){if(!init)return;try{let d=await api('/api/kira/shop');$('shopList').innerHTML=d.items.map(x=>`<div class="shop-item"><div class="shop-top"><div><b>${esc(x.name)}</b><div class="tiny muted">${esc(x.description)}</div></div><div>${x.owned?'<span class="owned">Куплено</span>':'<span class="price">'+x.price+' 🪙</span>'}</div></div>${x.owned?'':`<button class="secondary" onclick="buyItem('${esc(x.key)}')">Купить</button>`}</div>`).join('')}catch(e){$('shopList').textContent='Не удалось загрузить магазин.'}}
async function buyItem(key){try{let d=await api('/api/kira/shop/'+encodeURIComponent(key),{method:'POST',body:'{}'});toast(d.message);await loadMe();await loadShop()}catch(e){toast('Покупка не удалась')}}
async function loadCharacter(){if(!init)return;try{dndState=await api('/api/dnd/character');$('dndName').value=dndState.name||'';$('dndRace').value=dndState.race||'';$('dndClass').value=dndState.class||'';$('dndLevel').value=dndState.level||1;$('dndHp').value=dndState.hp??10;$('dndAc').value=dndState.ac??10;$('dndNotes').value=dndState.notes||''}catch(e){toast('Не удалось загрузить героя')}}
async function saveCharacter(){try{let d={...dndState,name:$('dndName').value,race:$('dndRace').value,class:$('dndClass').value,level:+$('dndLevel').value||1,hp:+$('dndHp').value||0,ac:+$('dndAc').value||0,notes:$('dndNotes').value};await api('/api/dnd/character',{method:'PUT',body:JSON.stringify(d)});dndState=d;toast('Герой сохранён ✦')}catch(e){toast('Ошибка сохранения героя')}}
async function roll(sides){try{let d=await api('/api/dnd/roll',{method:'POST',body:JSON.stringify({sides,modifier:0,mode:'normal'})});$('rollResult').textContent=d.result+'  ·  '+d.expression}catch(e){toast('Кубик не бросился')}}
async function loadCampaigns(){if(!init)return;try{let rows=await api('/api/dnd/campaigns');$('campaigns').innerHTML=rows.length?rows.map(c=>`<div class="campaign"><b>${esc(c.name)}</b><div class="tiny muted">код ${esc(c.code)}</div></div>`).join(''):'<div class="notice">Кампаний пока нет.</div>'}catch(e){$('campaigns').innerHTML='<div class="notice">Не удалось загрузить кампании.</div>'}}
async function createCampaign(){try{let d=await api('/api/dnd/campaigns',{method:'POST',body:JSON.stringify({name:$('campaignName').value||'Новая кампания'})});$('campaignName').value='';toast('Код: '+d.code);loadCampaigns()}catch(e){toast('Не удалось создать кампанию')}}
async function joinCampaign(){let code=$('joinCode').value.trim();if(!code)return;try{await api('/api/dnd/campaigns/join',{method:'POST',body:JSON.stringify({code})});$('joinCode').value='';toast('Ты в кампании');loadCampaigns()}catch(e){toast('Код не найден')}}
async function loadCommands(){if(commands.length){renderCommands();return}try{let d=await api('/api/kira/commands');commands=d.commands;renderCommands()}catch(e){$('commandsList').textContent='Не удалось загрузить команды.'}}
function renderCommands(){let q=($('commandSearch').value||'').toLocaleLowerCase('ru');let rows=commands.filter(x=>(x.usage+' '+x.description+' '+x.section).toLocaleLowerCase('ru').includes(q));$('commandsList').innerHTML=rows.map(x=>`<div class="command"><div class="tiny muted">${esc(x.section)}</div><div class="command-top"><code>${esc(x.usage)}</code><button class="secondary" style="flex:0 0 auto;padding:7px 9px" onclick="copyCmd('${esc(x.usage).replace(/'/g,'&#39;')}')">Копировать</button></div><div class="muted tiny">${esc(x.description)}</div></div>`).join('')||'<div class="notice">Ничего не найдено.</div>'}
function copyCmd(v){navigator.clipboard?.writeText(v);toast('Команда скопирована')}
async function sendChat(){let p=$('chatPrompt'),v=p.value.trim();if(!v)return;let box=$('chatBox'),me=document.createElement('div');me.className='notice';me.style.marginLeft='12%';me.textContent='Ты: '+v;box.appendChild(me);p.value='';p.disabled=true;try{let d=await api('/api/kira/chat',{method:'POST',body:JSON.stringify({message:v})});let m=document.createElement('div');m.className='notice';m.style.marginRight='12%';m.textContent='Кира: '+d.answer;box.appendChild(m);box.scrollTop=box.scrollHeight}catch(e){toast('AI временно недоступен')}finally{p.disabled=false;p.focus()}} $('chatPrompt')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();sendChat()}}); const first=(location.hash||'#home').slice(1);go(['home','chat','profile','shop','commands','memory'].includes(first)?first:'home');loadMe();
</script></body></html>'''
